local LOGO_B64 = ""
local function b64decode(data)
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, #chars do map[string.byte(chars, i)] = i - 1 end
    local out, n, acc, bits = {}, 0, 0, 0
    for i = 1, #data do
        local v = map[string.byte(data, i)]
        if v then
            acc = acc * 64 + v
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local byte = math.floor(acc / (2 ^ bits))
                acc = acc - byte * (2 ^ bits)
                n = n + 1
                out[n] = string.char(byte)
            end
        end
    end
    return table.concat(out)
end
local function LoadLogo()
    local getAsset = getcustomasset or getsynasset
    if type(writefile) ~= "function" or type(getAsset) ~= "function" then return nil end
    local ok, asset = pcall(function()
        if type(delfile) == "function" and type(isfile) == "function" and isfile("LazyJiro_logo.png") then pcall(delfile, "LazyJiro_logo.png") end
        writefile("ObsessionHub_logo_v3.png", b64decode(LOGO_B64))
        return getAsset("ObsessionHub_logo_v3.png")
    end)
    if ok and type(asset) == "string" and asset ~= "" then return asset end
    return nil
end

