    })

    local accT, accF = 0, 0
    reg(RunService.Heartbeat:Connect(function(dt)
        if not bubble.Visible then accT, accF = 0, 0; return end
        accT = accT + dt; accF = accF + 1
        if accT < 0.5 then return end
        fpsLabel.Text = math.floor(accF / accT + 0.5) .. " FPS"
        accT, accF = 0, 0
        local ping
        pcall(function() ping = Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
        if ping then
            pingLabel.Text = math.floor(ping + 0.5) .. "ms"
            local lit = ping < 100 and 3 or (ping < 200 and 2 or 1)
            local col = ping < 100 and Theme.Good or (ping < 200 and Color3.fromRGB(255, 196, 70) or Theme.Accent)
            for i, b in ipairs(barParts) do
                b.BackgroundColor3 = col
                b.BackgroundTransparency = i <= lit and 0 or 0.7
            end
        end
    end))
